SELECT b.*
FROM ai_brief b
WHERE b.id = #{briefId}
  AND b.tenant_id = #{tenantId}
  AND b.deleted = 0
  AND (
      b.project_id = #{projectId}
      OR EXISTS (
          SELECT 1
          FROM ai_project_brief_ref ref
          WHERE ref.project_id = #{projectId}
            AND ref.brief_id = b.id
            AND ref.tenant_id = #{tenantId}
            AND ref.deleted = 0
      )
  )
  AND (
      b.create_by = #{userId}
      OR EXISTS (
          SELECT 1
          FROM ai_brief_collaborator collaborator
          WHERE collaborator.brief_id = b.id
            AND collaborator.user_id = #{userId}
            AND collaborator.tenant_id = #{tenantId}
            AND collaborator.status = 1
            AND collaborator.deleted = 0
      )
  )
LIMIT 1

SELECT COUNT(DISTINCT accessible.brief_id)
FROM (
    SELECT b.id AS brief_id
    FROM ai_brief b
    INNER JOIN ai_project p
        ON p.id = b.project_id
       AND p.tenant_id = #{tenantId}
       AND p.owner_id = #{userId}
       AND p.deleted = 0
    WHERE b.tenant_id = #{tenantId}
      AND b.deleted = 0
    UNION
    SELECT ref.brief_id
    FROM ai_project_brief_ref ref
    INNER JOIN ai_project p
        ON p.id = ref.project_id
       AND p.tenant_id = #{tenantId}
       AND p.owner_id = #{userId}
       AND p.deleted = 0
    INNER JOIN ai_brief b
        ON b.id = ref.brief_id
       AND b.tenant_id = #{tenantId}
       AND b.deleted = 0
    WHERE ref.tenant_id = #{tenantId}
      AND ref.deleted = 0
) accessible

SELECT COUNT(DISTINCT candidate.id)
FROM ai_brief candidate
WHERE candidate.tenant_id = #{tenantId}
  AND candidate.deleted = 0
  AND candidate.id IN

      #{briefId}

  AND NOT EXISTS (
      SELECT 1
      FROM ai_project direct_project
      WHERE direct_project.id = candidate.project_id
        AND direct_project.tenant_id = #{tenantId}
        AND direct_project.owner_id = #{userId}
        AND direct_project.deleted = 0
  )
  AND NOT EXISTS (
      SELECT 1
      FROM ai_project_brief_ref existing_ref
      INNER JOIN ai_project linked_project
          ON linked_project.id = existing_ref.project_id
         AND linked_project.tenant_id = #{tenantId}
         AND linked_project.owner_id = #{userId}
         AND linked_project.deleted = 0
      WHERE existing_ref.brief_id = candidate.id
        AND existing_ref.tenant_id = #{tenantId}
        AND existing_ref.deleted = 0
  )
